import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import path from "node:path";
import { loopar, CHILD_POSITION_COLUMN } from "loopar";
import { bootTestTenant } from "../support/tenant.js";

/*
 * Staffing bills through the erp: approved timesheet hours become Draft erp
 * Invoices (one per client and period, generated by the Staffing Client).
 * Each timesheet line is billed once; cancelling the invoice or deleting its
 * draft frees its hours. Covers the 1.13.0 migration (payment terms to the
 * Customer, the removed Staffing Invoice).
 */

const root = process.cwd();
const staffing = (...p) => import(path.join(root, "apps", "staffing", ...p));

let t, Installer, billing, clients;
let client, customer, site;
const PERIOD = { from: "2026-11-02", to: "2026-11-08" };

before(async () => {
  t = await bootTestTenant({ apps: ["erp"] });
  ({ default: Installer } = await staffing("installer.js"));
  await t.run(() => new Installer({ app_name: "staffing" }).install());
  billing = await staffing("modules", "staffing-billing", "billing.js");
  clients = await staffing("modules", "staffing", "shared", "clients.js");

  await t.run(async () => {
    loopar.mail.send = async () => ({ ok: true });
    client = await clients.createClient({ customer: { customer_name: "Acme Rentals", email: "ap@acme.test" } });
    customer = await loopar.db.getValue("Staffing Client", "customer", client);

    const siteDoc = await loopar.newDocument("Staffing Site", { site_name: "Airport Lot", client, status: "Active" });
    await siteDoc.save();
    site = siteDoc.name;

    const position = await loopar.newDocument("Staffing Position", { name: "Detailer", active: 1 });
    position.__KEEP_NAME__ = true;
    await position.save();
  });
});
after(async () => { await t?.teardown(); });

/** An Approved timesheet with `days` lines of `hours` each (raw rows: a Draft rebuilds its lines from shifts). */
async function approvedTimesheet(name, { days = 5, hours = 9, overtime = 5, rate = 30, lineSite = site } = {}) {
  const q = () => loopar.db.qx();
  await q()("Staffing Timesheet").insert({
    name, worker: "W-1", week_start: PERIOD.from, status: "Approved",
    total_hours: days * hours, regular_hours: days * hours - overtime, overtime_hours: overtime,
  });
  const { id } = await loopar.db.getRow("Staffing Timesheet", name, ["id"]);
  for (let d = 0; d < days; d++) {
    await q()("Staffing Timesheet Line").insert({
      name: `${name}-${d}`, parent_id: id, parent_document: "Staffing Timesheet", [CHILD_POSITION_COLUMN]: d,
      work_date: `2026-11-0${2 + d}`, site: lineSite, position: "Detailer", hours, pay_rate: 18, bill_rate: rate, overtime_multiplier: 1.5,
    });
  }
}

const stamps = async (timesheet) => {
  const { id } = await loopar.db.getRow("Staffing Timesheet", timesheet, ["id"]);
  return [...new Set((await loopar.db.getAll("Staffing Timesheet Line", ["invoice"], { parent_id: id })).map((l) => l.invoice || null))];
};

test("approved hours become one Draft erp invoice per client, with overtime on its own line", async () => {
  await t.run(async () => {
    await approvedTimesheet("TS-1");
    const result = await billing.generateInvoices(PERIOD);
    assert.equal(result.created.length, 1);
    assert.equal(result.lines, 5);

    const invoice = await loopar.getDocument("Invoice", result.created[0]);
    assert.equal(invoice.status, "Draft");
    assert.equal(invoice.customer, customer);
    assert.deepEqual([invoice.generator_document, invoice.generator_name], ["Staffing Client", client]);
    assert.equal(String(invoice.period_start).slice(0, 10), PERIOD.from);
    assert.equal(String(invoice.period_end).slice(0, 10), PERIOD.to);

    const lines = await loopar.db.getAll("Billing Line", ["section", "description", "quantity", "unit", "rate", "amount"], { parent_id: invoice.id, parent_document: "Invoice" });
    assert.deepEqual(lines.map((l) => [l.section, l.description, Number(l.quantity), l.unit, Number(l.rate)]), [
      ["Airport Lot", "Detailer — regular hours", 40, "Hour", 30],
      ["Airport Lot", "Detailer — overtime", 5, "Hour", 45],
    ]);
    assert.equal(Number(invoice.total), 1425);
    assert.deepEqual(await stamps("TS-1"), [invoice.name]);

    // Billed once: nothing is left for the same period.
    assert.deepEqual((await billing.generateInvoices(PERIOD)).created, []);
  });
});

test("deleting the draft, or cancelling the issued invoice, frees its hours", async () => {
  await t.run(async () => {
    const [first] = await stamps("TS-1");
    await (await loopar.getDocument("Invoice", first)).delete();
    assert.deepEqual(await stamps("TS-1"), [null]);

    const { created: [second] } = await billing.generateInvoices({ ...PERIOD, client });
    assert.ok(second && second !== first);
    const invoice = await loopar.getDocument("Invoice", second);
    await invoice.issue();
    assert.deepEqual(await stamps("TS-1"), [second]);

    await (await loopar.getDocument("Invoice", second)).cancel({ reason: "Wrong period" });
    assert.equal(await loopar.db.getValue("Invoice", "status", second), "Cancelled");
    assert.deepEqual(await stamps("TS-1"), [null]);
  });
});

test("a position with a billing item is invoiced as that item, at the agreed rate", async () => {
  await t.run(async () => {
    const item = await loopar.newDocument("Item", { name: "SRV-DETAIL", item_name: "Detailing labor", item_type: "Service", rate: 99 });
    item.__KEEP_NAME__ = true;
    await item.save();
    await loopar.db.qx()("Staffing Position").where({ name: "Detailer" }).update({ item: item.name });

    const result = await billing.generateInvoices(PERIOD);
    assert.equal(result.created.length, 1);
    const { id } = await loopar.db.getRow("Invoice", result.created[0], ["id"]);
    const lines = await loopar.db.getAll("Billing Line", ["item", "rate", "quantity"], { parent_id: id, parent_document: "Invoice" });
    assert.deepEqual(lines.map((l) => [l.item, Number(l.rate), Number(l.quantity)]), [[item.name, 30, 40], [item.name, 45, 5]]);
  });
});

test("the update moves a client's old payment terms to its Customer and removes the old invoice structure", async () => {
  await t.run(async () => {
    const q = () => loopar.db.qx();
    // What 1.12.x left: the terms on the client, and the empty invoice tables.
    await q().schema.alterTable("Staffing Client", (tb) => { tb.string("payment_terms"); });
    await q()("Staffing Client").where({ name: client }).update({ payment_terms: "Net 30" });
    await q().schema.createTable("Staffing Invoice", (tb) => { tb.increments("id"); tb.string("name"); });
    await q().schema.createTable("Staffing Invoice Line", (tb) => { tb.increments("id"); tb.string("name"); });
    await q()("Workflow").insert({ name: "Staffing Invoice", document: "Staffing Invoice", app: "staffing" }).catch(() => {});
  });

  await t.run(() => new Installer({ app_name: "staffing" }).install(true));

  await t.run(async () => {
    const q = () => loopar.db.qx();
    assert.equal(await loopar.db.getValue("Customer", "payment_terms", customer), "Net 30");
    assert.equal(await billing.clientPaymentTerms(client), "Net 30");
    assert.equal(await q().schema.hasColumn("Staffing Client", "payment_terms"), false);
    assert.equal(await q().schema.hasTable("Staffing Invoice"), false);
    assert.equal(await q().schema.hasTable("Staffing Invoice Line"), false);
    assert.equal(await loopar.db.count("Workflow", { name: "Staffing Invoice" }), 0);
    assert.equal(loopar.getRef("Staffing Invoice", false), null);
  });
});
